-- Federation Spatial Contract 1.0 — MoneySweep-owned PostGIS plane.
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE SCHEMA IF NOT EXISTS federation_spatial;
CREATE TABLE IF NOT EXISTS federation_spatial.layers (layer_id text PRIMARY KEY,layer_version text NOT NULL,producer_repo text NOT NULL CHECK (producer_repo='moneysweep-pr'),domain text NOT NULL,title text NOT NULL,crs text NOT NULL DEFAULT 'EPSG:4326',bbox geometry(Polygon,4326),feature_count bigint NOT NULL DEFAULT 0 CHECK(feature_count>=0),manifest jsonb NOT NULL,logical_sha256 char(64) NOT NULL,source_manifestation_sha256 char(64) NOT NULL,certification_state text NOT NULL DEFAULT 'OPEN',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS federation_spatial.features (feature_id text PRIMARY KEY,layer_id text NOT NULL REFERENCES federation_spatial.layers(layer_id) ON DELETE CASCADE,producer_repo text NOT NULL CHECK (producer_repo='moneysweep-pr'),domain text NOT NULL,feature_class text NOT NULL,geom geometry(Geometry,4326),altitude jsonb,valid_time tstzrange,properties jsonb NOT NULL DEFAULT '{}'::jsonb,geometry_source text NOT NULL,coordinate_method text NOT NULL,coordinate_confidence text NOT NULL,logical_sha256 char(64) NOT NULL,source_manifestation_sha256 char(64) NOT NULL,provenance jsonb NOT NULL DEFAULT '[]'::jsonb,evidence_state text NOT NULL,review_state text NOT NULL,identity_semantics text NOT NULL DEFAULT 'CANDIDATE_NOT_IDENTITY',updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS federation_spatial_features_geom_gix ON federation_spatial.features USING gist(geom);
CREATE INDEX IF NOT EXISTS federation_spatial_features_props_gin ON federation_spatial.features USING gin(properties);
CREATE INDEX IF NOT EXISTS federation_spatial_features_layer_idx ON federation_spatial.features(layer_id);
CREATE TABLE IF NOT EXISTS federation_spatial.relations (relation_id bigserial PRIMARY KEY,relation_type text NOT NULL,source_feature_id text NOT NULL REFERENCES federation_spatial.features(feature_id) ON DELETE CASCADE,target_feature_id text NOT NULL REFERENCES federation_spatial.features(feature_id) ON DELETE CASCADE,method text NOT NULL,algorithm_version text NOT NULL,distance_m double precision,threshold_m double precision,confidence text NOT NULL,identity_semantics text NOT NULL DEFAULT 'CANDIDATE_NOT_IDENTITY',evidence_state text NOT NULL DEFAULT 'COMPUTED',computed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(relation_type,source_feature_id,target_feature_id,method,algorithm_version));
CREATE INDEX IF NOT EXISTS federation_spatial_rel_source_idx ON federation_spatial.relations(source_feature_id);
CREATE INDEX IF NOT EXISTS federation_spatial_rel_target_idx ON federation_spatial.relations(target_feature_id);
